import { useId, useState } from 'react';
import { JxAlert, JxButton, JxInput, JxSelect, JxSwitch } from '@jinx-ui/react';

const ROLES = [
  { value: 'viewer', label: 'Наблюдатель' },
  { value: 'editor', label: 'Редактор' },
  { value: 'admin', label: 'Администратор' },
];

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

export default function TeamInviteForm() {
  const formId = useId();
  const [email, setEmail] = useState('');
  const [touched, setTouched] = useState(false);
  const [role, setRole] = useState('viewer');
  const [notify, setNotify] = useState(true);
  const [invitedEmail, setInvitedEmail] = useState<string | null>(null);

  const isValid = EMAIL_PATTERN.test(email.trim());
  const showError = touched && !isValid;

  const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!isValid) {
      setTouched(true);
      return;
    }
    setInvitedEmail(email.trim());
    setEmail('');
    setTouched(false);
  };

  return (
    <div
      className="jx-stack"
      style={{ display: 'grid', gap: 'var(--jx-space-4)', maxWidth: 'var(--jx-size-md, 420px)' }}
    >
      {invitedEmail !== null && (
        <JxAlert
          variant="success"
          title="Приглашение отправлено"
          dismissible
          onDismiss={() => setInvitedEmail(null)}
        >
          {invitedEmail} получит доступ к команде.
        </JxAlert>
      )}

      <form
        onSubmit={handleSubmit}
        noValidate
        style={{ display: 'grid', gap: 'var(--jx-space-4)' }}
      >
        <JxInput
          id={`${formId}-email`}
          type="email"
          label="Рабочая почта"
          placeholder="name@company.com"
          value={email}
          onValueChange={setEmail}
          onBlur={() => setTouched(true)}
          invalid={showError}
          hint="Приглашение придёт на этот адрес и будет действовать 7 дней."
          error={showError ? 'Введите корректный адрес электронной почты.' : undefined}
          autoComplete="email"
          required
        />

        <JxSelect
          id={`${formId}-role`}
          label="Роль в команде"
          value={role}
          onValueChange={setRole}
          options={ROLES}
        />

        <JxSwitch
          id={`${formId}-notify`}
          label="Отправить уведомление"
          checked={notify}
          onCheckedChange={setNotify}
        />

        <JxButton type="submit" variant="primary" disabled={!isValid}>
          Отправить приглашение
        </JxButton>
      </form>
    </div>
  );
}

